  'invest.command.title': 'Fonctionnement de la commande',
  'invest.command.lead': 'La commande <code class="cmd">/invest</code> fait partie du wallet du chat. Elle fonctionne sur quatre niveaux :',
  'invest.command.l1': '<strong>Lister les opératrices :</strong> <code class="cmd">/invest</code> affiche Aave, Morpho, Ondo et xStocks.',
